const classified = $json.output?.[0]?.content?.[0]?.text ?? {};
const query = String(classified.query ?? '');
const text = 'I can only help with questions related to this website’s content and covered topics. Please rephrase your question within that scope.';
return [{ json: { type: 'text', query, text } }];

let output =
  $json?.output ??
  $json?.response?.output ??
  $json?.text ??
  $json;

if (typeof output === 'string') {
  let cleaned = output.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) cleaned = match[0];

  try {
    output = JSON.parse(cleaned);
  } catch {
    return [{ json: { type: 'text', text: cleaned } }];
  }
}

if (output && typeof output === 'object') {
  if (!output.type && Array.isArray(output.results)) {
    output.type = 'search_results';
  }

  output.results = Array.isArray(output.results)
    ? output.results.slice(0, 5).map(result => ({
        title: String(result.title ?? ''),
        url: String(result.url ?? ''),
        summary: String(result.summary ?? '')
      }))
    : [];

  return [{ json: output }];
}

return [{ json: { type: 'text', text: String(output ?? '') } }];

const output = { ...$json };

if (output.type === 'search_results') {
  output.query = String(output.query ?? '');
  output.results = Array.isArray(output.results) ? output.results : [];
  if (output.follow_up != null) {
    output.follow_up = String(output.follow_up);
  }
}

return [{ json: output }];

