const items = $input.all();

const classifier = $('OpenAI Intent and Language Classifier').first().json;
const classified = classifier.output?.[0]?.content?.[0]?.text ?? {};
const request = {
  chatInput: String(classified.query ?? ''),
  sessionId: String($('Normalize Webhook Payload').first().json.sessionId ?? '')
};

function meta(item) {
  return item.json?.metadata || item.json?.document?.metadata || {};
}
function urlOf(item) {
  const m = meta(item);
  return String(m.url || m.sourceUrl || item.json?.url || '').trim();
}
function titleOf(item) {
  const m = meta(item);
  return String(m.title || item.json?.title || 'Untitled').trim();
}
function textOf(item) {
  return String(item.json?.document?.pageContent || item.json?.pageContent || item.json?.content || '');
}
function scoreOf(item) {
  const score = item.json?.score ?? item.json?.similarity ?? null;
  return typeof score === 'number' ? score : null;
}
function cleanSnippet(text, maxLen = 1200) {
  return text.replace(/\s+/g, ' ').replace(/<\/?[^>]+(>|$)/g, '').trim().slice(0, maxLen);
}

const byUrl = new Map();
for (const item of items) {
  const url = urlOf(item);
  if (!url) continue;
  const score = scoreOf(item) ?? -999;
  const previous = byUrl.get(url);
  if (!previous || score > previous.score) {
    byUrl.set(url, {
      title: titleOf(item),
      url,
      score,
      snippet: cleanSnippet(textOf(item))
    });
  }
}

const documents = [...byUrl.values()]
  .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
  .slice(0, 20);

const context = documents.map((doc, index) =>
  `${index + 1}) ${doc.title}\nURL: ${doc.url}\nSNIPPET: ${doc.snippet}`
).join('\n\n---\n\n');

return [{
  json: {
    chatInput: request.chatInput,
    sessionId: request.sessionId,
    context,
    documents
  }
}];

const text = $json.text ?? $json.output?.[0]?.content?.[0]?.text ?? $json.output ?? '';
const classifier = $('OpenAI Intent and Language Classifier').first().json;
const query = classifier.output?.[0]?.content?.[0]?.text?.query ?? '';
return [{ json: { type: 'text', query: String(query), text: String(text).trim() } }];

// Accepts JSON, text/plain, or form-like webhook payloads and normalizes them.
const raw = $json.body;
let body = raw;

if (typeof raw === 'string') {
  try { body = JSON.parse(raw); }
  catch { body = { message: raw }; }
}

body = body && typeof body === 'object' ? body : { message: String(body ?? '') };

return [{
  json: {
    chatInput: String(body.message ?? body.query ?? body.text ?? '').trim(),
    sessionId: String(body.sessionId ?? body.session_id ?? $json.headers?.['x-chat-session'] ?? 'anonymous'),
    userAgent: String($json.headers?.['user-agent'] ?? ''),
    languageHint: body.language ?? null,
  }
}];
